    def do_restore(self, i, name):
        snap = self.saves.get(name)
        if snap is None:      # never saved: nothing to recover, row still logged
            self.log.append([i, 'restore', name])
            return
        node = snap[0]
        current = self.j_node
        if node != current:
            for entry, buddy in enumerate(self.buddies):
                if buddy[1] == node:
                    self.swap_to(entry)
                    break
            else:
                self.branch_to(node)
        self.apply_snapshot(snap)
        self.log.append([i, 'restore', name])

    def branch_to(self, node):
        """Reach ``node`` by journal walking, caching a copy when that is dear."""
        steps, join = self.path_to(node)
        if steps >= WALK_TO_CACHE:
            self.materialize()
        self.go_to(node, join)

